First, create your Redux store and cart reducer:

**cartSlice.js**
```js
import { createSlice } from '@reduxjs/toolkit';

export const cartSlice = createSlice({
  name: 'cart',
  initialState: {
    items: [],
    subtotal: 0,
    taxes: 0,
    total: 0,
  },
  reducers: {
    addItem(state, action) {
      const item = action.payload;
      const existingItem = state.items.find((i) => i.id === item.id);
      if (existingItem) {
        existingItem.quantity += item.quantity;
      } else {
        state.items.push({...item, quantity: item.quantity });
      }
      state.subtotal += item.price * item.quantity;
      state.taxes = state.subtotal * 0.08; // 8% tax rate
      state.total = state.subtotal + state.taxes;
    },
    removeItem(state, action) {
      const itemId = action.payload;
      const index = state.items.findIndex((i) => i.id === itemId);
      if (index >= 0) {
        state.items.splice(index, 1);
        state.subtotal -= state.items[index].price * state.items[index].quantity;
        state.taxes = state.subtotal * 0.08;
        state.total = state.subtotal + state.taxes;
      }
    },
    clearCart(state) {
      state.items = [];
      state.subtotal = 0;
      state.taxes = 0;
      state.total = 0;
    },
  },
});

export const { addItem, removeItem, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```

